  return `<article class="panel evidence-panel workflow-panel"><div class="panel-heading"><div><h2>Typical PM workflows <span class="count-badge">13 categories</span></h2><p>Specific categories stay visible, including zero activity and unclassified work</p></div>${search?`<label class="search-box">${icon('search')}<input id="query" placeholder="Find a workflow" value="${esc(state.query)}" aria-label="Find a workflow"></label>`:'<a href="#workflows" class="text-link">Explore workflows '+icon('right')+'</a>'}</div><div class="table-scroll"><table><thead><tr><th>PM workflow</th><th>Activities</th><th>Share</th><th>Verify & iterate</th><th>Deliverables</th><th>Adoption</th></tr></thead><tbody>${rows.map(w=>`<tr class="workflow-row" data-workflow="${w.id}"><td><strong class="workflow-name">${w.label}</strong><span class="workflow-description">${w.description}</span>${w.id==='unknown'?'<span class="classification-tag">Needs classification</span>':''}</td><td class="aggregate-number">${w.total}</td><td><span class="share-cell"><span class="mini-track"><i style="width:${w.share}%"></i></span>${w.share}%</span></td><td>${w.deepRate}% <span class="small-count">(${w.deep})</span></td><td>${w.artifacts}</td><td>${w.confirmed}</td></tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="no-workflow">No category matches this search.</p>':''}<div class="table-footer"><span>${icon('shield')}No individual names, task titles, prompts or session contents.</span><span>One workflow category per activity</span></div></article>`;
